import React, { useState } from "react";

function Login({ onLogin, message }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [loginType, setLoginType] = useState("user");

  const handleSubmit = (e) => {
    e.preventDefault();
    onLogin(username, password, loginType);
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-100">
      <div className="bg-white p-8 rounded-xl shadow-2xl w-full max-w-md">
        <h2 className="text-3xl font-bold text-center text-indigo-700 mb-6">
          Login
        </h2>

        <p className="text-sm text-gray-500 text-center mb-4">
          Select your login type and enter credentials.
        </p>

        <form onSubmit={handleSubmit} className="space-y-4">
          {/* Login Type */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Login Type
            </label>
            <select
              value={loginType}
              onChange={(e) => setLoginType(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500"
            >
              <option value="user">User</option>
              <option value="admin">Admin</option>
            </select>
          </div>

          {/* Username */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Username
            </label>
            <input
              type="text"
              required
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500"
            />
          </div>

          {/* Password */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Password
            </label>
            <input
              type="password"
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500"
            />
          </div>

          {/* Login button */}
          <button
            type="submit"
            className="w-full mt-4 px-4 py-2 bg-indigo-600 text-white font-semibold rounded-lg hover:bg-indigo-700 transition duration-200"
          >
            Login
          </button>
        </form>

        {/* Error Message */}
        {message && message.type === "error" && (
          <div className="p-3 mt-4 rounded-lg text-sm bg-red-100 text-red-700 text-center">
            {message.text}
          </div>
        )}
      </div>
    </div>
  );
}

export default Login;
